<div id="spotlight-modal" class="fixed inset-0 z-50 hidden items-center justify-center p-4" style="background-color:rgba(0,0,0,0.6);" role="dialog" aria-modal="true">
    <div class="relative w-full max-w-lg overflow-hidden rounded-md bg-background shadow-xl border border-border">
        <button type="button" id="spotlight-modal-close" aria-label="Close" class="absolute right-3 top-3 z-10 grid h-8 w-8 place-items-center rounded-full bg-background/80 backdrop-blur text-foreground hover:bg-secondary cursor-pointer">
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4"><path d="M18 6 6 18"></path><path d="m6 6 12 12"></path></svg>
        </button>
        <div class="aspect-[4/3] w-full overflow-hidden bg-slate-900/5 dark:bg-slate-950 flex items-center justify-center">
            <img id="spotlight-modal-image" src="" alt="" class="h-full w-full object-contain max-h-[70vh]">
        </div>
        <div class="p-6">
            <h3 id="spotlight-modal-product" class="text-base sm:text-lg font-bold text-foreground leading-snug"></h3>
            <p id="spotlight-modal-quote" class="mt-3 text-sm leading-relaxed text-muted-foreground italic"></p>
        </div>
    </div>
</div>

<script>
(function(){
    var modal = document.getElementById('spotlight-modal');
    if (!modal) return;
    function openModal(btn){
        document.getElementById('spotlight-modal-image').src = btn.dataset.image;
        document.getElementById('spotlight-modal-product').textContent = btn.dataset.product || '';
        var quoteEl = document.getElementById('spotlight-modal-quote');
        if (btn.dataset.quote && btn.dataset.quote.trim() !== '') {
            quoteEl.textContent = '“' + btn.dataset.quote + '”';
            quoteEl.style.display = 'block';
        } else {
            quoteEl.textContent = '';
            quoteEl.style.display = 'none';
        }
        modal.classList.remove('hidden');
        modal.classList.add('flex');
        document.body.style.overflow = 'hidden';
    }
    function closeModal(){
        modal.classList.add('hidden');
        modal.classList.remove('flex');
        document.body.style.overflow = '';
    }
    document.querySelectorAll('.spotlight-modal-trigger').forEach(function(btn){
        btn.addEventListener('click', function(){ openModal(btn); });
    });
    document.getElementById('spotlight-modal-close').addEventListener('click', closeModal);
    modal.addEventListener('click', function(e){ if(e.target === modal) closeModal(); });
    document.addEventListener('keydown', function(e){ if(e.key === 'Escape') closeModal(); });
})();
</script>
